<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Leaderboard · Dynasty HQ Fantasy Predictions</title><link rel="stylesheet" href="assets/predictions.css"></head><body><header class="site-header"><div class="header-inner"><div class="header-brand"><div class="brand-title">Dynasty <span>HQ</span></div><div class="brand-sub">Fantasy Predictions</div></div><div class="header-meta"><a class="nav-link" href="history.php">History</a><a class="nav-link" href="league.php">Leagues</a></div></div></header><main class="main"><section class="hero compact"><h1>Leaderboard</h1><p class="subtitle">Half-PPR prediction accuracy</p></section><section class="panel"><div class="leaderboard-table"><div class="leaderboard-row leaderboard-head"><span>Player</span><span>Points</span><span>Correct</span><span>Settled</span><span>Accuracy</span></div><?php foreach ($leaders as $leader): $accuracy = (int) $leader['settled_picks'] > 0 ? 100 * (int) $leader['wins'] / (int) $leader['settled_picks'] : 0; ?><div class="leaderboard-row"><strong><?php echo predictions_escape($leader['display_name']); ?></strong><span><?php echo (int) $leader['total_points']; ?></span><span><?php echo (int) $leader['wins']; ?></span><span><?php echo (int) $leader['settled_picks']; ?></span><span><?php echo number_format($accuracy, 1); ?>%</span></div><?php endforeach; ?><?php if ($leaders === []): ?><p class="empty-state">No settled picks yet.</p><?php endif; ?></div></section></main></body></html>
